using System;
using System.Linq;
using System.Collections.Generic;
namespace IdleIntelligence.Core
{
 public static class ChallengeRules
 {
  public static bool Active(GameState s)=>s.Challenges.Run!=null;
  public static bool Is(GameState s,string id)=>s.Challenges.Run?.id==id;
  public static int Index(string id)=>Array.IndexOf(ChallengeBalance.Families,id);
  public static ChallengeDefinition Definition(string id,int stage)=>stage<1||stage>69||Index(id)<0?null:ChallengeBalance.Stages[Index(id)*69+stage-1];
  public static ChallengeDefinition Current(GameState s)=>Active(s)?Definition(s.Challenges.Run.id,s.Challenges.Run.stage):null;
  public static double Bonus(GameState s,string id){int i=Index(id);return i<0||Is(s,id)?0:ChallengeBalance.RewardCoefficient*Math.Log(1+s.Challenges.Progress.stages[i]);}
  public static bool Link(GameState s,int index)=>!Is(s,"fragmented-network")||s.Challenges.Run.networkLinks.Contains(Balance.Hardware[index].Id);
  public static string EntryBlock(GameState s,string id,int stage,string[] items,string[] links)
  {
   var d=Definition(id,stage);if(d==null)return "Ungültige Stufe";if(Active(s))return "Challenge läuft bereits";if(stage>s.Challenges.Progress.stages[Index(id)]+1)return "Vorherige Stufe abschließen";if(s.Prestige.resets<1)return "Erstes Prestige erforderlich";int hardware=Array.FindIndex(Balance.Hardware,h=>h.Id==d.EntryHardware);if(!s.Industry.discovered[hardware]&&s.Hardware[hardware]==0)return "Hardware entdecken: "+Balance.Hardware[hardware].Name;
   if(id=="fragmented-network"&&Game.Level(s,"distributedInference")==0)return "Verteilte Inferenz erforschen";if(id=="closed-supply-chain"&&Game.Level(s,"blueprints")==0)return "Baupläne erforschen";
   if(items==null||links==null||items.Distinct().Count()!=items.Length||items.Any(item=>!s.Workshop.inventory.Any(i=>i.id==item))||id=="no-items"&&items.Length>0)return "Ungültige Ausrüstung";
   var selected=s.Workshop.inventory.Where(i=>items.Contains(i.id)).ToArray();if(selected.Select(i=>i.type).Distinct().Count()!=selected.Length)return "Jeder Itemtyp nur einmal";
   var slots=Workshop.ActiveSlots(s);int extra=0;foreach(string family in new[]{"processor","core","research"})extra+=Math.Max(0,selected.Count(i=>Workshop.Definition(i).Family==family)-ItemBalance.Slots.Where((slot,n)=>slots[n]&&!slot.StartsWith("universal")&&slot.Replace("Aux","")==family).Count());if(extra>slots.Skip(6).Count(v=>v)||items.Length>slots.Count(v=>v))return "Ausrüstung passt nicht in Slots";
   if(id=="fragmented-network"&&(links.Length<d.Links||links.Length>d.NetworkLimit||links.Distinct().Count()!=links.Length||links.Any(link=>Array.FindIndex(Balance.Hardware,h=>h.Id==link)<1)))return "Nachbarschaftsverbindungen wählen";return null;
  }
  public static GameState Start(GameState state,string id,int stage,string runId,string[] itemIds=null,string[] links=null)
  {
   var d=Definition(id,stage);if(d==null||string.IsNullOrEmpty(runId)||runId.Length>200)return state;itemIds=itemIds??(id=="no-items"?Array.Empty<string>():state.Workshop.equipped.Where(v=>!string.IsNullOrEmpty(v)).ToArray());links=links??Balance.Hardware.Skip(1).Take(d.NetworkLimit).Select(h=>h.Id).ToArray();if(EntryBlock(state,id,stage,itemIds,links)!=null)return state;
   var s=Game.New(state.SavedAt);s.Tutorial="done";s.Prestige.resets=state.Prestige.resets;s.Prestige.Total=state.Prestige.Total;s.Prestige.hardwareAuto=(bool[])state.Prestige.hardwareAuto.Clone();s.Workshop.nodes=(string[])state.Workshop.nodes.Clone();s.Prestige.known=(string[])state.Prestige.known.Clone();s.Workshop.permanentSlots=(string[])state.Workshop.permanentSlots.Clone();s.Meta.axioms=(int[])state.Meta.axioms.Clone();s.Meta.total=ScientificNumber.FromData(state.Meta.total).ToData();s.Meta.models=(int[])state.Meta.models.Clone();s.Workshop.activeModel=state.Workshop.activeModel;s.Workshop.activeModelLevel=state.Workshop.activeModelLevel;s.Workshop.reducedMotion=state.Workshop.reducedMotion;s.Research=(int[])state.Research.Clone();s.Workshop.blueprintReward=state.Workshop.blueprintReward;
   var c=s.Challenges;c.Progress.stages=(int[])state.Challenges.Progress.stages.Clone();c.Progress.unlocks=(string[])state.Challenges.Progress.unlocks.Clone();c.Main=state.Copy();c.Run=new ChallengeRun{id=id,stage=stage,runId=runId,startedAt=s.SavedAt,networkLinks=id=="fragmented-network"?(string[])links.Clone():Array.Empty<string>()};
   var activeSlots=Workshop.ActiveSlots(state);var used=new HashSet<int>();s.Workshop.inventory=itemIds.Select((item,n)=>{var i=state.Workshop.inventory.First(v=>v.id==item).Copy();i.id="loadout-"+n;i.locked=i.challengeCopy=true;i.materialBasis=new double[ItemBalance.ComponentIds.Length];i.recoveryUsed=new double[ItemBalance.ComponentIds.Length];i.missingMaterialBasis=true;return i;}).ToArray();
   c.Run.loadout=s.Workshop.inventory.Select(i=>i.Copy()).ToArray();foreach(var item in s.Workshop.inventory){string family=Workshop.Definition(item).Family;int slot=Array.FindIndex(ItemBalance.Slots,v=>{int n=Array.IndexOf(ItemBalance.Slots,v);return activeSlots[n]&&!used.Contains(n)&&!v.StartsWith("universal")&&v.Replace("Aux","")==family;});if(slot<0)slot=Enumerable.Range(6,2).First(n=>activeSlots[n]&&!used.Contains(n));used.Add(slot);s.Workshop.equipped[slot]=item.id;}
   return id=="no-taps"?Game.Buy(s,"calculator"):s;
  }
  public static ScientificNumber GoalValue(GameState s,string id)
  {
   var m=s.Challenges.Run.metrics;switch(id){case "passive-credits":case "regular-credits":return ScientificNumber.FromData(m.credits);case "compute/s":return Game.Compute(s);case "paid-milestones":return ScientificNumber.From(m.milestones);case "early-depth":return ScientificNumber.From(Math.Max(s.Hardware[0],s.Hardware[1]));case "generated-data":return ScientificNumber.FromData(m.data);case "paid-training":return ScientificNumber.From(m.training);case "paid-research":case "research":return ScientificNumber.From(m.research);case "class-purchases":return ScientificNumber.From(m.hardwarePurchases);case "quality":return ScientificNumber.From(s.Quality);case "efficiency":return ScientificNumber.From(s.Efficiency);case "credits/s":return Game.Income(s);case "users/s":return Game.Users(s);case "different-areas":return ScientificNumber.From(m.researchAreas.Length);case "local-items":return ScientificNumber.From(m.craftedIds.Length);case "local-rarity":return ScientificNumber.From(m.craftRarity);case "crafted-types":return ScientificNumber.From(m.craftedTypes.Length);case "research-data-spent":return ScientificNumber.FromData(m.researchData);case "active-links":return ScientificNumber.From(Enumerable.Range(1,s.Hardware.Length-1).Count(n=>Link(s,n)&&Game.Level(s,"distributedInference")>0&&s.Hardware[n]>0&&s.Hardware[n-1]>=IndustryBalance.LinkPrevious));case "prestiges":return ScientificNumber.From(m.prestiges);case "minimum-int-per-reset":return ScientificNumber.FromData(m.minimumINT);default:throw new ArgumentException("Unknown challenge goal");}
  }
  public static bool Ready(GameState s)
  {var d=Current(s);return d!=null&&d.Goals.All(g=>GoalValue(s,g.Id).CompareTo(g.Target)>=0)&&!s.Hardware.Skip(d.ClassLimit).Any(n=>n>0)&&(!Is(s,"efficiency-lock")||s.Quality==0)&&(!Is(s,"quality-lock")||s.Efficiency==0);}
  public static GameState Return(GameState state,bool success,string expectedRunId=null)
  {
   if(!Active(state)||state.Challenges.Main==null||expectedRunId!=null&&state.Challenges.Run.runId!=expectedRunId||success&&!Ready(state))return state;state=state.Copy();PauseMain(state,state.SavedAt);var run=state.Challenges.Run;var s=state.Challenges.Main.Copy();var p=s.Challenges.Progress;int family=Index(run.id);if(success){bool first=p.stages[family]<run.stage;if(first){p.stars+=Definition(run.id,run.stage).Stars;p.stages[family]=Math.Max(p.stages[family],run.stage);}p.completions[family]++;double seconds=(state.SavedAt-run.startedAt)/1000;p.bestSeconds[family]=p.bestSeconds[family]<0?seconds:Math.Min(seconds,p.bestSeconds[family]);int total=p.stages.Sum();p.unlocks=p.unlocks.Union(ChallengeBalance.AutomationUnlocks.Where((id,n)=>total>=ChallengeBalance.AutomationTotals[n])).ToArray();}p.lastReturnId=run.runId;p.lastSuccess=success;return s;
  }
  public static void PauseMain(GameState s,double at)
  {if(!Active(s)||s.Challenges.Main==null)return;var main=s.Challenges.Main;double delta=Math.Max(0,at-main.SavedAt),old=main.SavedAt;if(delta==0)return;main.Workshop.runStartedAt+=delta;main.Meta.cycleStartedAt+=delta;if(main.LastTap>=0)main.LastTap+=delta;if(main.ActiveUntil>old)main.ActiveUntil+=delta;if(main.CooldownUntil>old)main.CooldownUntil+=delta;main.SavedAt=at;}
  public static void Produced(GameState s,ScientificNumber credits,ScientificNumber data)
  {if(!Active(s))return;var m=s.Challenges.Run.metrics;m.credits=ScientificNumber.FromData(m.credits).Add(credits).ToData();m.data=ScientificNumber.FromData(m.data).Add(data).ToData();}
  public static void ResearchCompleted(GameState s,Job job)
  {if(!Active(s))return;var m=s.Challenges.Run.metrics;string area=new[]{"data","architecture","model","materials","automation"}[Workshop.ResearchArea(job.id)];m.research++;m.researchAreas=m.researchAreas.Union(new[]{area}).ToArray();m.researchData=ScientificNumber.FromData(m.researchData).Add(job.paidDataRecorded?ScientificNumber.FromData(job.paidData):ScientificNumber.Zero).ToData();}
  public static void ItemCrafted(GameState s,ItemInstance item)
  {if(!Active(s))return;var m=s.Challenges.Run.metrics;m.craftedIds=m.craftedIds.Concat(new[]{item.id}).ToArray();m.craftedTypes=m.craftedTypes.Union(new[]{item.type}).ToArray();m.craftRarity=Math.Max(m.craftRarity,item.rarity);}
  public static void Validate(GameState s)
  {
   var c=s.Challenges;var p=c?.Progress;if(p==null||p.schema!=1||p.stages==null||p.stages.Length!=10||p.stages.Any(v=>v<0||v>69)||p.stars<0||p.completions==null||p.completions.Length!=10||p.completions.Any(v=>v<0||v>9007199254740991L)||p.bestSeconds==null||p.bestSeconds.Length!=10||p.bestSeconds.Any(v=>!ScientificNumber.Finite(v)||v< -1)||p.unlocks==null||p.unlocks.Any(id=>!ChallengeBalance.AutomationUnlocks.Contains(id))||p.unlocks.Distinct().Count()!=p.unlocks.Length)throw new FormatException("Invalid challenge progress");
   if(c.Run==null){if(c.Main!=null||s.Workshop.inventory.Any(i=>i.challengeCopy))throw new FormatException("Orphan challenge state");return;}var r=c.Run;if(c.Main==null||c.Main.Challenges.Run!=null||c.Main.Challenges.Main!=null||c.Main.SavedAt>s.SavedAt||c.Main.SavedAt<r.startedAt||Definition(r.id,r.stage)==null||r.catalogVersion!=2||string.IsNullOrEmpty(r.runId)||r.runId.Length>200||!ScientificNumber.Finite(r.startedAt)||r.startedAt<0||r.startedAt>s.SavedAt||r.networkLinks==null||r.networkLinks.Distinct().Count()!=r.networkLinks.Length||r.networkLinks.Any(id=>Array.FindIndex(Balance.Hardware,h=>h.Id==id)<1))throw new FormatException("Invalid isolated challenge session");var d=Current(s);if(s.Hardware.Skip(d.ClassLimit).Any(n=>n>0)||Is(s,"efficiency-lock")&&s.Quality>0||Is(s,"quality-lock")&&s.Efficiency>0||Is(s,"fragmented-network")&&(r.networkLinks.Length<d.Links||r.networkLinks.Length>d.NetworkLimit)||r.loadout==null||r.loadout.Length>Workshop.ActiveSlots(s).Count(v=>v)||Is(s,"no-items")&&r.loadout.Length>0)throw new FormatException("Forbidden challenge progression");foreach(var copy in r.loadout){var item=s.Workshop.inventory.FirstOrDefault(i=>i.id==copy.id);if(item==null||!item.challengeCopy||item.type!=copy.type||item.rarity!=copy.rarity||item.level!=copy.level||item.forge!=copy.forge||item.legacyLevelFactor!=copy.legacyLevelFactor)throw new FormatException("Mutated challenge loadout");}var m=r.metrics;if(m==null||new[]{m.prestiges,m.hardwarePurchases,m.milestones,m.training,m.research,m.quality,m.efficiency}.Any(n=>n<0||n>9007199254740991L)||m.craftRarity<0||m.craftRarity>5||m.researchAreas==null||m.researchAreas.Any(id=>!new[]{"data","architecture","model","materials","automation"}.Contains(id))||m.researchAreas.Distinct().Count()!=m.researchAreas.Length||m.craftedIds==null||m.craftedIds.Distinct().Count()!=m.craftedIds.Length||m.craftedTypes==null||m.craftedTypes.Distinct().Count()!=m.craftedTypes.Length||m.craftedTypes.Any(id=>Workshop.Index(id)<0))throw new FormatException("Invalid challenge metrics");foreach(var n in new[]{m.credits,m.data,m.minimumINT,m.researchData})ScientificNumber.FromData(n);Game.Validate(c.Main);
  }
 }
}
